fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    // Preconditions from spec: assume x.len() > 0 && y.len() > 0

    let m = y.len();
    let n = x.len();

    // result.0: for each i in 0..m, a vector containing all elements of x (length n)
    let mut grid_x = Vec::with_capacity(m);
    for _ in 0..m {
        // clone x into a new vector for this row
        let mut row_x = Vec::with_capacity(n);
        for j in 0..n {
            row_x.push(x[j]);
        }
        grid_x.push(row_x);
    }

    // result.1: for each i in 0..m, a vector of length n filled with y[i]
    let mut grid_y = Vec::with_capacity(m);
    for i in 0..m {
        let mut row_y = Vec::with_capacity(n);
        let val = y[i];
        for _ in 0..n {
            row_y.push(val);
        }
        grid_y.push(row_y);
    }

    (grid_x, grid_y)
}